-- Charts 2.0 Phase 1B, founder-selected five-source evidence store.
-- Filename generated by supabase migration new charts2_source_evidence_v1
-- using the repository-pinned CLI 2.107.0 in GitHub run 44335133638.
-- NO collector activation, scoring, publication, or change to Chart V2.
begin;

-- The existing platform_private schema is unexposed to anon/authenticated.
-- Explicit deny remains in force for all new relation objects.
create table platform_private.charts2_source_methods_v1 (
  source_key text primary key check (
    source_key in ('apple_ke','shazam_ke','mdundo_ke','youtube_ke','audiomack_ke')
  ),
  market text not null default 'KE' check (market = 'KE'),
  expected_depth integer not null check (
    (source_key = 'shazam_ke' and expected_depth = 200) or
    (source_key <> 'shazam_ke' and expected_depth = 100)
  ),
  exact_endpoint text,
  reviewed_method text,
  review_state text not null default 'held'
    check (review_state in ('held','collector_admitted','retired')),
  reviewed_by uuid,
  reviewed_at timestamptz,
  authorization_expires_at timestamptz,
  access_evidence_sha256 text
    check (access_evidence_sha256 is null or access_evidence_sha256 ~ '^[a-f0-9]{64}$'),
  method_revision integer not null default 0 check (method_revision >= 0),
  updated_at timestamptz not null default now(),
  constraint charts2_method_admission_complete check (
    review_state <> 'collector_admitted' or
    (exact_endpoint is not null and length(exact_endpoint) between 15 and 2048
     and reviewed_method is not null and reviewed_by is not null
     and reviewed_at is not null and authorization_expires_at > reviewed_at
     and access_evidence_sha256 is not null and method_revision > 0)
  )
);

insert into platform_private.charts2_source_methods_v1
  (source_key, expected_depth)
values
  ('apple_ke',100),('shazam_ke',200),('mdundo_ke',100),
  ('youtube_ke',100),('audiomack_ke',100);

-- Exactly one atomic, immutable parsed observation set per original.
-- Store original bytes in private Storage using create-only upload. A trusted
-- server must re-read, SHA-256 verify, and then commit this receipt.
create table platform_private.charts2_capture_receipts_v1 (
  id uuid primary key default gen_random_uuid(),
  source_key text not null references
    platform_private.charts2_source_methods_v1(source_key),
  market text not null default 'KE' check (market = 'KE'),
  receipt_schema text not null default 'charts2-original-receipt/v1'
    check (receipt_schema = 'charts2-original-receipt/v1'),
  source_endpoint text not null check (length(source_endpoint) between 15 and 2048),
  method_revision integer check (method_revision is null or method_revision > 0),
  capture_mode text not null
    check (capture_mode in ('research_original_upload','service_original')),
  observed_at timestamptz not null,
  provider_updated_at timestamptz,
  provider_week_ending_date date,
  native_period_authority text not null default 'unknown'
    check (native_period_authority in ('unknown','observed_as_of','provider_declared_end_date','native_complete_interval')),
  original_bucket text not null default 'charts2-evidence-private-v1'
    check (original_bucket = 'charts2-evidence-private-v1'),
  original_object_key text not null unique
    check (length(original_object_key) between 8 and 500 and
           original_object_key !~ '(^/|\\.\\.|[[:cntrl:]])'),
  original_byte_length integer not null
    check (original_byte_length between 1 and 4000000),
  original_sha256 text not null
    check (original_sha256 ~ '^[a-f0-9]{64}$'),
  original_verified_at timestamptz not null,
  original_content_type text not null
    check (original_content_type in ('text/html','text/csv','application/json')),
  expected_depth integer not null,
  observed_depth integer not null
    check (observed_depth >= 1 and observed_depth <= expected_depth),
  observed_status text generated always as
    (case when observed_depth = expected_depth then 'succeeded'
          else 'partial_depth' end) stored,
  observations jsonb not null check (
    jsonb_typeof(observations) = 'array'
    and jsonb_array_length(observations) = observed_depth
  ),
  parser_version text not null check (length(parser_version) between 1 and 120),
  candidate_only boolean not null default true check (candidate_only = true),
  can_score boolean not null default false check (can_score = false),
  can_publish boolean not null default false check (can_publish = false),
  created_at timestamptz not null default now(),
  unique (source_key, original_sha256),
  constraint charts2_receipt_native_depth check (
    (source_key = 'shazam_ke' and expected_depth = 200) or
    (source_key <> 'shazam_ke' and expected_depth = 100)
  )
);

-- Ensure that a parsed original's numbered positions really are contiguous
-- and that the original recording identifiers aren't duplicated within it.
create function platform_private.charts2_guard_receipt_rows_v1()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  item jsonb;
  i integer;
  provider_id text;
  seen_ids text[] := '{}'::text[];
begin
  for i in 1..new.observed_depth loop
    item := new.observations -> (i-1);
    if jsonb_typeof(item) <> 'object' or
       jsonb_typeof(item->'rank') <> 'number' or
       item->>'rank' <> i::text then
      raise exception 'charts2_capture_rank_sequence_invalid';
    end if;
    provider_id := item->>'provider_track_id';
    if provider_id is not null and provider_id <> '' then
      if provider_id = any(seen_ids) then
        raise exception 'charts2_capture_duplicate_provider_identity';
      end if;
      seen_ids := array_append(seen_ids, provider_id);
    end if;
  end loop;
  if new.original_verified_at < new.observed_at - interval '1 day' then
    raise exception 'charts2_original_verification_clock_invalid';
  end if;
  return new;
end;
$$;
create trigger charts2_guard_receipt_rows_v1
before insert on platform_private.charts2_capture_receipts_v1
for each row execute function platform_private.charts2_guard_receipt_rows_v1();

-- Append-only. A correction or retry inserts a separately audited receipt.
create function platform_private.charts2_reject_receipt_mutation_v1()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'charts2_evidence_is_immutable';
end;
$$;
create trigger charts2_receipt_immutable_v1
before update or delete on platform_private.charts2_capture_receipts_v1
for each row execute function platform_private.charts2_reject_receipt_mutation_v1();

alter table platform_private.charts2_source_methods_v1 enable row level security;
alter table platform_private.charts2_capture_receipts_v1 enable row level security;
revoke all on platform_private.charts2_source_methods_v1 from public,anon,authenticated;
revoke all on platform_private.charts2_capture_receipts_v1 from public,anon,authenticated;
revoke all on function platform_private.charts2_guard_receipt_rows_v1() from public,anon,authenticated;
revoke all on function platform_private.charts2_reject_receipt_mutation_v1() from public,anon,authenticated;

-- Private Storage bucket definition only. Original object writes and SHA
-- readback MUST use the Storage API with create-only semantics.
insert into storage.buckets
  (id,name,public,file_size_limit,allowed_mime_types)
values
  ('charts2-evidence-private-v1','charts2-evidence-private-v1',
   false,4000000,array['text/html','text/csv','application/json']::text[]);

-- The bucket has no anon/authenticated Storage policies. Existing
-- storage.objects policies are bucket-scoped to other products.
-- No release, program, edition, scoring, scheduled job or source admission
-- is changed by this migration.
commit;
